const [query, setQuery] = useState("");
const [view, setView] = useState("grid");
const [modal, setModal] = useState(false);
const [editing, setEditing] = useState(null);
const [menu, setMenu] = useState(null);
const [toast, setToast] = useState("");
const save = (next) => {
	setItems(next);
	localStorage.setItem("bookmarked-items", JSON.stringify(next));
};
const notify = (msg) => {
	setToast(msg);
	setTimeout(() => setToast(""), 2200);
};
const filtered = useMemo(() => items.filter((item) => {
	const matchesTab = active === "All bookmarks" || active === "Favorites" && item.favorite || active === "Unread" && !item.read || item.tags.includes(active.toLowerCase());
	const haystack = `${item.title} ${item.description} ${item.domain} ${item.tags.join(" ")}`.toLowerCase();
	return matchesTab && haystack.includes(query.toLowerCase());
}), [
	items,
	active,
	query
]);
const allTags = [...new Set(items.flatMap((x) => x.tags))].slice(0, 6);
const toggleFavorite = (id) => save(items.map((x) => x.id === id ? {
	...x,
	favorite: !x.favorite
} : x));
const remove = (id) => {
	save(items.filter((x) => x.id !== id));
	setMenu(null);
	notify("Bookmark moved to trash");
};
const openForm = (item = null) => {
	setEditing(item);
	setModal(true);
	setMenu(null);
};
const submit = (e) => {
	e.preventDefault();
	const fd = new FormData(e.currentTarget);
	let rawUrl = fd.get("url").trim();
	if (!/^https?:\/\//i.test(rawUrl)) rawUrl = `https://${rawUrl}`;
	let domain = rawUrl;
	try {
		domain = new URL(rawUrl).hostname.replace(/^www\./, "");
	} catch {}
	const data = {
		title: fd.get("title").trim(),
		url: rawUrl,
		domain,
		description: fd.get("description").trim(),
		tags: fd.get("tags").split(",").map((t) => t.trim().toLowerCase()).filter(Boolean).slice(0, 3)
	};
	if (editing) save(items.map((x) => x.id === editing.id ? {
		...x,
		...data
	} : x));
	else save([{
		id: Date.now(),
		...data,
		color: [
			"#EF7B57",
			"#213B35",
			"#D98B37",
			"#346D57"
		][items.length % 4],
		icon: data.title[0]?.toUpperCase() || "B",
		favorite: false,
		read: false,
		date: "Just now"
	}, ...items]);
	setModal(false);
	notify(editing ? "Bookmark updated" : "Bookmark saved");
};
